import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as s,o as i,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"Write AGENTS.md for the repo","description":"AGENTS.md is a README for coding agents. Put install, test, and conventions in the repo instead of repeating them in chat.","frontmatter":{"title":"Write AGENTS.md for the repo","description":"AGENTS.md is a README for coding agents. Put install, test, and conventions in the repo instead of repeating them in chat.","domain":"tech","tags":["prompt"],"navOrder":30,"llm":[15],"prev":{"text":"How to write prompts","link":"/tech/prompt/"},"next":{"text":"Agent engineering","link":"/tech/prompt/agent-engineering-practices"}},"headers":[],"relativePath":"tech/prompt/agents-doc.md","filePath":"tech/prompt/agents-doc.md","lastUpdated":1788250975000}'),n={name:"tech/prompt/agents-doc.md"};function o(l,t,r,d,h,p){return i(),s("div",null,[...t[0]||(t[0]=[a(`<h1 id="write-agents-md-for-the-repo" tabindex="-1">Write AGENTS.md for the repo <a class="header-anchor" href="#write-agents-md-for-the-repo" aria-label="Permalink to &quot;Write AGENTS.md for the repo&quot;">​</a></h1><p><strong>Bottom line:</strong> rules you repeat in every chat belong in <code>AGENTS.md</code> at the repo root. It is a README for coding agents, not a second human contributing guide.</p><p>The format is defined at <a href="https://agents.md/" target="_blank" rel="noreferrer">agents.md</a>, now stewarded by the Agentic AI Foundation under the Linux Foundation. Cursor, Codex, GitHub Copilot, Gemini CLI, Claude Code, and others read it.</p><h2 id="audience-and-non-goals" tabindex="-1">Audience and non-goals <a class="header-anchor" href="#audience-and-non-goals" aria-label="Permalink to &quot;Audience and non-goals&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Prerequisites</strong></td><td>You can already write a task / constraints / output prompt from <a href="/tech/prompt/">How to write prompts</a></td></tr><tr><td><strong>You will be able to</strong></td><td>Land an <code>AGENTS.md</code> that an assistant will actually execute</td></tr><tr><td><strong>Not this page</strong></td><td>A full product tour → <a href="/products/">Products</a>. Multi-agent orchestration → <a href="/tech/patterns/agent/">Agents</a></td></tr></tbody></table><h2 id="what-problem-it-solves" tabindex="-1">What problem it solves <a class="header-anchor" href="#what-problem-it-solves" aria-label="Permalink to &quot;What problem it solves&quot;">​</a></h2><p><code>README.md</code> is for humans: what the project is, how to run it, how to contribute.</p><p><code>AGENTS.md</code> is for assistants: which package manager, how to test, which directories are off-limits, which checks must be green. That text makes a README too long. Leaving it unwritten makes every assistant guess.</p><p>There are no required fields. It is ordinary Markdown. On conflict: <strong>the nearest <code>AGENTS.md</code> to the file being edited wins</strong>. The current user chat overrides everything.</p><h2 id="minimal-template" tabindex="-1">Minimal template <a class="header-anchor" href="#minimal-template" aria-label="Permalink to &quot;Minimal template&quot;">​</a></h2><p>Copy this to the repo root and replace the commands. This site itself uses the same rule: <code>pnpm</code> at the root, never <code>npm install</code> there.</p><div class="language-md vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;"># AGENTS.md</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Setup commands</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Install: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm install\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (repo root only)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do not run </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`npm install\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> at the root</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Docs: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm docs:dev\`</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Build: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm docs:build\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Code style</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ES modules only (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`import\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> / </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`export\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> The root package has </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`&quot;type&quot;: &quot;module&quot;\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Testing instructions</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Run </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm docs:build\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> before you commit</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Also run </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`pnpm ppt:build\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> if you touched slides</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do not claim the site is fine after editing one page: sidebar links must resolve to real </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\`.md\`</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> files</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-weight:bold;--shiki-dark:#79B8FF;--shiki-dark-font-weight:bold;">## Security</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do not write tokens, local MCP config, or home-directory paths into docs</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Mark unverified command names, flags, and URLs instead of inventing them</span></span></code></pre></div><p>The official site recommends covering how to run, how to test, style, and security. Add commit / PR / deploy notes when the team actually needs them.</p><h2 id="working-rules" tabindex="-1">Working rules <a class="header-anchor" href="#working-rules" aria-label="Permalink to &quot;Working rules&quot;">​</a></h2><ol><li><strong>Commands must be real.</strong> Run <code>pnpm docs:build</code> once before you write it down. Agents will execute the checks you list.</li><li><strong>Write actions, not a persona.</strong> &quot;You are a world-class engineer&quot; adds almost nothing. The package manager and the forbidden commands do.</li><li><strong>Nest files in a monorepo.</strong> Official example: the main OpenAI repo had 88 <code>AGENTS.md</code> files at the time of writing. Closest file wins.</li><li><strong>Do not duplicate the README.</strong> Keep the human quick start in README. Put the long assistant contract here.</li><li><strong>Migrate old names</strong> with <code>mv AGENT.md AGENTS.md &amp;&amp; ln -s AGENTS.md AGENT.md</code>.</li></ol><p>Gemini CLI can pin the filename in <code>.gemini/settings.json</code>:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;context&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;fileName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;AGENTS.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span></code></pre></div><p>Aider uses <code>read: AGENTS.md</code> in <code>.aider.conf.yml</code>. Newer tools look at the root file by default.</p><h2 id="how-tools-read-it" tabindex="-1">How tools read it <a class="header-anchor" href="#how-tools-read-it" aria-label="Permalink to &quot;How tools read it&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Default file</th><th>Also see</th></tr></thead><tbody><tr><td>Cursor</td><td>Root / nested <code>AGENTS.md</code></td><td><code>.cursor/rules</code>, <a href="/products/cursor/">Cursor</a></td></tr><tr><td>Claude Code</td><td><code>AGENTS.md</code> + <code>CLAUDE.md</code></td><td><a href="/products/claude/claude-code.html">Claude Code</a></td></tr><tr><td>Codex</td><td><code>AGENTS.md</code></td><td><a href="/products/codex/">Codex</a></td></tr><tr><td>Copilot Coding Agent</td><td><code>AGENTS.md</code></td><td><a href="/products/copilot/">Copilot</a></td></tr></tbody></table><p>This repo&#39;s own sample is the root <code>AGENTS.md</code> plus <code>Claude.md</code>. Open those instead of inventing a persona.</p><h2 id="bad-vs-good" tabindex="-1">Bad vs good <a class="header-anchor" href="#bad-vs-good" aria-label="Permalink to &quot;Bad vs good&quot;">​</a></h2><p><strong>Bad:</strong> a long persona and a fake command (<code>npm test</code> at this repo root).</p><p><strong>Good:</strong> real commands and bans (<code>pnpm</code> only, <code>pnpm docs:build</code>, no tokens in docs).</p><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li><strong>A second README</strong> that restates the pitch and skips install / test commands.</li><li><strong>Fake commands</strong>, such as <code>npm test</code> in a <code>pnpm</code> repo.</li><li><strong>Replacing the product page.</strong> Cursor rules and <code>CLAUDE.md</code> still live in those products. <code>AGENTS.md</code> is the cross-tool minimum.</li><li><strong>Expecting it to replace the current task.</strong> &quot;Fix the contrast on Settings&quot; still belongs in the chat.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/tech/prompt/agent-engineering-practices.html">Agent engineering practices</a></li><li><a href="/tech/prompt/context-agent-engineering.html">Context for agents</a></li><li><a href="/tech/patterns/agent/skills.html">Skills</a></li></ul><h2 id="go-deeper" tabindex="-1">Go deeper <a class="header-anchor" href="#go-deeper" aria-label="Permalink to &quot;Go deeper&quot;">​</a></h2><ul><li>Format and examples: <a href="https://agents.md/" target="_blank" rel="noreferrer">agents.md</a></li><li>Search GitHub for <code>filename:AGENTS.md</code> (the official site cites 60k+ projects)</li><li>This repo&#39;s root <code>AGENTS.md</code> / <code>Claude.md</code> as a live sample</li></ul>`,30)])])}const E=e(n,[["render",o]]);export{u as __pageData,E as default};
